const DEAD = new Set(["7brand-sa.com","abhais.edu.sa","acic-ksa.com","al-omaier.com","alassimi-law.com","albassamschools.edu.sa","alemaaralareq.com","alexiahotels.com","alhadafelamny.com","alhamads.com","alharbiholding.com","alkifahprecast.com","almosanadah.net","alnagah-clean.com","aom-company.com","app.beyah.sa","aybmedical.company","bbd.sa","be.besmartksa.com","bml.med.sa","bn-shmashyer.com","cgshool.com.sa","citytechsa.com","company.sa","doroob-roze.com","eamaraseer.sa","eisa4044.sa","elsakrplastic.com","etspices.com","farajalofi.com","firstgulfcompany.com","flglc.com","flyto-sky.com","friend2020.com","goharamarket.com","goldenl.sa","greenarrowac.com","h-sakan.com","health-dimension.com","hospital.kau.edu.sa","jewaralsafwahsa.com","kaah.med.sa","kinona.sa","lanaiis.in","lcc.sa","lifelines-store.com","mah.sa","masadar.com.sa","medad-medical.com","medpromedicals.com","nano.com.sa","nequlalarabia.com","odata.type","orisderma.com","qistlaw.sa","rct.edu.sa","rehabalmadinaa.com","saad-international.com","safarplustravels.net","salama-team.com","sattahmakkhahservice.com","sawarifuture.com","sepcoarabia.com","shodeshtravel.com","shorfarealestate.com","square1sa.com","sultanrec.com","thekrsch.com","toolsworldksa.redintek.in","tzaidd.com","untitled.tld","uod.edu.sa","wajen.sa","wwww.printazone.com","69317660ca139.site123.me","6a1b9bc50bcbb.site123.me","6a221a25a1202.site123.me","ain.com","alshmukh.adalo.com","api.whatsapp.com","apps.apple.com","aqspepsi.wordpress.com","buruj.sa","cdn.qr-code-generator.com","cholarestaurant.coreninesolutions.com","en.zoomlion.com","jasminegardenhotel.seebooking.com","kfsh.med.sa","m.facebook.com","me.marsh.com","qr.finedinemenu.com","sa.hm.com","srexpress.com","training.alkhaleej.com.sa","-ascott.com"]);

const PLATFORM = new Set(["booking.com","expedia.com","google.com","goo.gl","maps.app.goo.gl","instagram.com","facebook.com","tiktok.com","x.com","twitter.com","linkedin.com","snapchat.com","framer.com","flowcode.com","myqrcode.com","instabio.cc","n9.cl","qrco.de","salla.sa","vip.com","adobe.com","sentry.io","wixpress.com","yaschools.com","bayut.sa","jomla.me","stagheaddesigns.com","indiantypefoundry.com","micahrich.com","reserval.com","mysecurecloudhost.com","hyattrestaurants.com","marriott.com","radissonhotels.com","millenniumhotels.com","swissotel.com","warwickhotels.com","wyndham.com","otis.com"]);

const PLATFORM_SUFFIXES = [".site123.me",".lovable.app",".adalo.com",".weebly.com",".wordpress.com",".foodics.online",".classera.com",".bookmystay.io",".seebooking.com",".joodbooking.com",".verticalbooking.com",".hotelmold.top",".baab.com",".zaaer.co",".finedinemenu.com",".redintek.in",".wiandk.app",".coreninesolutions.com",".pics.ee",".qr-code-generator.com"];

const PLACEHOLDER = new Set(["company.com","mysite.com","domain.com","email.com","example.com","example.org","yourwebsite.com","yourdomain.com","yoursite.com","compant.com","blocks.com","hq.com","realesatate.com","untitled.tld","domain.tld","test.com","site.com","mail.com"]);
const PLACEHOLDER_LOCALS = new Set(["example","your","yourname","youremail","yourmail","email","test","name","firstname","username","sample","demo"]);

const RE_EMAIL = /^[a-z0-9._%+'-]+@[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+$/;

function normalise(raw) {
  if (!raw) return "";
  let s = String(raw).trim();
  try { s = decodeURIComponent(s); } catch (e) { s = s.replace(/%20/g, " "); }
  s = s.replace(/^mailto:/i, "");
  const parts = s.split(/[,;\s<>()\[\]]+/).map(p => p.trim().toLowerCase()).filter(Boolean);
  for (const p of parts) if (RE_EMAIL.test(p)) return p;
  return "";
}

const out = [];
const seen = new Set();
const dropped = { suppressed: 0, duplicate: 0, sent: 0, invalid: 0, dead: 0, platform: 0, placeholder: 0, repeat: 0 };

for (const item of $input.all()) {
  const j = item.json;
  if (j.property_suppressed === true) { dropped.suppressed++; continue; }
  if (j.property_duplicate === true) { dropped.duplicate++; continue; }
  if (j.property_campaign_sent === true) { dropped.sent++; continue; }

  const email = normalise(j.property_email || j.email || "");
  if (!email) { dropped.invalid++; continue; }

  const domain = email.split("@")[1];
  const local = email.split("@")[0];
  if (DEAD.has(domain)) { dropped.dead++; continue; }
  if (PLATFORM.has(domain) || PLATFORM_SUFFIXES.some(s => domain.endsWith(s))) { dropped.platform++; continue; }
  if (PLACEHOLDER.has(domain) || PLACEHOLDER_LOCALS.has(local)) { dropped.placeholder++; continue; }
  if (seen.has(email)) { dropped.repeat++; continue; }
  seen.add(email);

  // The template reads company_name_clean; this DB stores the title in Name.
  const company = (j.property_company_name_clean || j.property_name || j.name || "").toString().trim();
  if (!company) { dropped.invalid++; continue; }

  out.push({ json: Object.assign({}, j, { property_email: email, property_company_name_clean: company }) });
  if (out.length >= MAX_PER_RUN) break;
}

console.log("guard passed:", out.length, "| dropped:", JSON.stringify(dropped));
return out;

// Pair each DNS answer back to its lead by position — the HTTP node preserves input order.
const leads = $('Guard: Validate Before Send').all();
const answers = $input.all();

const out = [];
const dropped = { nxdomain: 0, no_mx: 0 };
let unresolved = 0;

for (let i = 0; i < leads.length; i++) {
  const r = (answers[i] && answers[i].json) || {};
  const status = r.Status;

  // Status 3 = NXDOMAIN: the domain does not exist.
  if (status === 3) { dropped.nxdomain++; continue; }

  // Status 0 = NOERROR. Records of type 15 are MX. No MX means no mail server:
  // 48 of the confirmed bounces were exactly this case, so it is worth dropping.
  if (status === 0) {
    const hasMx = Array.isArray(r.Answer) && r.Answer.some(a => a.type === 15);
    if (!hasMx) { dropped.no_mx++; continue; }
    out.push(leads[i]);
    continue;
  }

  // Anything else (SERVFAIL, timeout, the request itself failed) is not evidence
  // of a bad address. Let it through and let the bounce handler judge it.
  unresolved++;
  out.push(leads[i]);
}

console.log('MX check passed:', out.length, '| dropped:', JSON.stringify(dropped), '| unresolved (allowed):', unresolved);
return out;
